"""Regenerate diagnostic analysis from scrubbed JFR in a fresh private directory.

Run only after timing is complete and disclosure-verification.json has passed.
This executes the preserved JFR extractor and analyzer, never the application.
The analyzer copy changes only its original recorded FileWrite path comparison.
"""

import argparse
import difflib
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile


HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
DEFAULT_JDK = Path("/workspace/scratch/d0a0e51b9386/toolchain/jdk-25.0.5+8")


def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def read(path):
    return json.loads(path.read_text())


def ranked(items):
    return isinstance(items, list) and items and all(isinstance(x, dict) and set(x) == {"name", "value"}
                                                   for x in items)


def compare_analysis(before, after, path="$", ties=None):
    """Require exact semantic equality, apart from equal-weight top-N tie order/selection.

    The original analyzer builds some Counters from sets. Python's randomized set
    iteration may change the order of equal-weight entries and which tie is kept
    at a top-N boundary. This is explicitly recorded, never applied to other data.
    """
    if ties is None:
        ties = []
    if before == after:
        return ties
    if ranked(before) and ranked(after):
        require(len(before) == len(after), "Ranked list lengths differ at " + path)
        old_weights, new_weights = [x["value"] for x in before], [x["value"] for x in after]
        require(old_weights == sorted(old_weights, reverse=True) and new_weights == old_weights,
                "Ranked weights differ at " + path)
        old = {x["name"]: x["value"] for x in before}
        new = {x["name"]: x["value"] for x in after}
        require(len(old) == len(before) and len(new) == len(after), "Repeated ranked names at " + path)
        cutoff = old_weights[-1]
        require({k: v for k, v in old.items() if v > cutoff} == {k: v for k, v in new.items() if v > cutoff},
                "Ranked entries above the cutoff differ at " + path)
        require(all(old[k] == new[k] for k in old.keys() & new.keys()), "Ranked common weights differ at " + path)
        require(all(old[k] == cutoff for k in old.keys() - new.keys())
                and all(new[k] == cutoff for k in new.keys() - old.keys()), "Non-tie ranked selection differs at " + path)
        ties.append({"path": path, "cutoffWeight": cutoff, "sameEntriesDifferentOrderOnly": old == new,
                     "replacedEqualWeightBoundaryEntries": len(old.keys() - new.keys())})
    elif isinstance(before, dict) and isinstance(after, dict):
        require(before.keys() == after.keys(), "Analysis keys differ at " + path)
        for key in before:
            compare_analysis(before[key], after[key], path + "." + key, ties)
    elif isinstance(before, list) and isinstance(after, list):
        require(len(before) == len(after), "Analysis list length differs at " + path)
        for index, (old, new) in enumerate(zip(before, after)):
            compare_analysis(old, new, path + f"[{index}]", ties)
    else:
        raise ValueError("Analysis value differs at " + path)
    return ties


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--execute-after-timing", action="store_true")
    parser.add_argument("--jdk", type=Path, default=DEFAULT_JDK)
    args = parser.parse_args()
    require(args.execute_after_timing, "Timing must have ended before diagnostic regeneration")
    receipt_path = HERE / "delivery-profiles/disclosure-verification.json"
    disclosure = read(receipt_path)
    require(disclosure["status"] == "passed" and disclosure["safeToPackage"], "Disclosure proof did not pass")
    output = HERE / "delivery-profiles/analysis-regeneration-verification.json"
    require(not os.path.lexists(output), "Regeneration receipt must be new")
    java = args.jdk.resolve(strict=True) / "bin/java"
    work = Path(tempfile.mkdtemp(prefix="materializer-jfr-regeneration-", dir=ROOT.parent))
    extractor = HERE / "ExtractJfr.java"
    analyzer = HERE / "analyze-profiles.py"
    watched = {str(path): sha(path) for path in (extractor, analyzer, receipt_path, Path(__file__).resolve())}
    before = analyzer.read_text()
    old = "e.get('path') == str(folder / 'samples.jsonl')"
    new = "e.get('path') == " + repr(str(HERE) + "/") + " + folder.name + '/samples.jsonl'"
    require(before.count(old) == 1, "The sole analyzer path substitution is no longer unique")
    after = before.replace(old, new)
    derivative = work / "analyze-profiles.py"
    derivative.write_text(after)
    patch = work / "analyzer-path-relocation.patch"
    patch.write_text("".join(difflib.unified_diff(before.splitlines(keepends=True), after.splitlines(keepends=True),
                                               fromfile="a/analyze-profiles.py", tofile="b/analyze-profiles.py")))
    environment = os.environ.copy()
    removed_overrides = []
    for name in ("JAVA_TOOL_OPTIONS", "JDK_JAVA_OPTIONS", "_JAVA_OPTIONS"):
        if environment.pop(name, None) is not None:
            removed_overrides.append(name)
    # Stable regeneration tie order; the original ranking's ties are audited explicitly below.
    environment["PYTHONHASHSEED"] = "0"
    commands, profiles = [], []
    for record in disclosure["recordings"]:
        mode = record["mode"]
        source = HERE / ("frozen-" + mode)
        folder = work / source.name
        folder.mkdir()
        sanitized = ROOT / record["sanitized"]["path"]
        require(sha(sanitized) == record["sanitized"]["sha256"], "Sanitized recording identity changed")
        watched[str(sanitized)] = record["sanitized"]["sha256"]
        for name in ("samples.jsonl", "arrival-trace.jsonl"):
            watched[str(source / name)] = sha(source / name)
            shutil.copyfile(source / name, folder / name)
        command = [str(java), "-Xms64m", "-Xmx512m", str(extractor), str(sanitized),
                   str(folder / "events.jsonl"), str(folder / "event-counts.json")]
        commands.append({"argv": command, "cwd": str(ROOT)})
        with (work / (mode + "-extraction.log")).open("xb") as log:
            result = subprocess.run(command, cwd=ROOT, env=environment, stdout=log, stderr=subprocess.STDOUT)
        require(result.returncode == 0, "Diagnostic extractor failed; private work is preserved")
        counts = read(folder / "event-counts.json")
        require(counts == record["retainedEventCounts"], "Sanitized extraction counts differ from full disclosure audit")
        original_expansion = source / "events.jsonl"
        original_hash = sha(original_expansion)
        regenerated_hash = sha(folder / "events.jsonl")
        require(original_hash == regenerated_hash, "Selected performance event expansion changed")
        watched[str(original_expansion)] = original_hash
        watched[str(source / "profile-analysis.json")] = sha(source / "profile-analysis.json")
        profiles.append({"mode": mode, "sanitizedSha256": record["sanitized"]["sha256"],
                         "originalSelectedEventExpansionSha256": original_hash,
                         "regeneratedSelectedEventExpansionSha256": regenerated_hash,
                         "selectedEventExpansionBytes": (folder / "events.jsonl").stat().st_size,
                         "selectedEventExpansionByteIdentical": True, "allRetainedEventCountsMatch": True})
    command = [sys.executable, str(derivative)]
    commands.append({"argv": command, "cwd": str(ROOT)})
    with (work / "analyzer.log").open("xb") as log:
        result = subprocess.run(command, cwd=ROOT, env=environment, stdout=log, stderr=subprocess.STDOUT)
    require(result.returncode == 0, "Derivative analyzer failed; private work is preserved")
    for record in profiles:
        mode = record["mode"]
        original_path = HERE / ("frozen-" + mode) / "profile-analysis.json"
        regenerated_path = work / ("frozen-" + mode) / "profile-analysis.json"
        original, regenerated = read(original_path), read(regenerated_path)
        differences = compare_analysis(original, regenerated)
        record.update({"originalAnalysisSha256": sha(original_path), "regeneratedAnalysisSha256": sha(regenerated_path),
                       "analysisExactJsonEquality": original == regenerated,
                       "analysisEquivalentApartFromEqualWeightRankedTies": True,
                       "equalWeightRankedTieDifferences": differences})
    require(all(sha(Path(path)) == value for path, value in watched.items()), "An original input changed during regeneration")
    proof = {"format": 1, "status": "passed", "applicationExecuted": False, "diagnosticJavaProcesses": 2,
             "disclosureReceiptSha256": sha(receipt_path), "originalInputsUnchanged": True,
             "privateWorkingDirectory": str(work), "java": str(java), "commands": commands,
             "removedJvmOverrideNames": removed_overrides, "regenerationPythonHashSeed": "0",
             "extractorSource": {"path": extractor.relative_to(ROOT).as_posix(), "sha256": sha(extractor)},
             "originalAnalyzerSource": {"path": analyzer.relative_to(ROOT).as_posix(), "sha256": sha(analyzer)},
             "derivativeAnalyzerSha256": sha(derivative), "analyzerPathRelocationPatch": patch.read_text(),
             "runnerSource": {"path": Path(__file__).resolve().relative_to(ROOT).as_posix(),
                              "sha256": sha(Path(__file__).resolve())},
             "analyzerOnlyRecordedPathComparisonChanged": True, "profiles": profiles,
             "interpretation": "The exact preserved extractor produces byte-identical selected performance-event JSONL from the "
                               "separate scrubbed recordings. The preserved analyzer, with only the original recorded FileWrite "
                               "path comparison relocated, reproduces every analysis field apart from explicitly listed order/selection "
                               "among equal-weight top-N ties caused by randomized set iteration. No timing experiment was run."}
    staging = work / output.name
    staging.write_text(json.dumps(proof, indent=2, sort_keys=True) + "\n")
    os.link(staging, output)  # Atomic no-overwrite publication on the same filesystem.
    print("Sanitized diagnostic regeneration passed; selected event bytes and all analysis statistics preserved.")
    print(output)


if __name__ == "__main__":
    try:
        main()
    except BaseException as error:
        # A tool/parser failure could quote an input value; do not print messages or traceback.
        print("Regeneration did not publish successfully; exception type: " + type(error).__name__, file=sys.stderr)
        raise SystemExit(1)
